('date_pit_crew_chill_v1', 'date_pit_crew', 1, 'date_night', 'chill', 'Your Date Has a Pit Crew', '{"id":"date_pit_crew_chill_v1","familyId":"date_pit_crew","version":1,"category":"date_night","intensity":"chill","title":"Your Date Has a Pit Crew","hook":"Two secret coaching messages. One couple trying to make the right call.","durationMinutes":30,"minParticipants":2,"maxParticipants":6,"cost":{"minMinor":0,"maxMinor":0,"currency":"USD","scope":"total","venueCostUnknown":true,"note":"Use supplies you already own. Purchases are optional. At a venue, confirm the complete group charge; your travel estimate is added separately."},"settings":["home","venue"],"interests":["mystery_date","elaborate_setups","surprises","making"],"roles":["mastermind","camera_person"],"preparation":"start_now","conflicts":[],"venuePermissionRequired":true,"arrangementRequired":false,"adultOnly":false,"supportsAdultContext":false,"requiresVolunteer":false,"beats":[{"label":"Setup","action":"Each partner asks a friend for a secret suggestion for an at-home snack or next free walking stop. Confirm both options fit your plans.","filming":"Record the two unopened messages without showing private chats.","caption":"Setup"},{"label":"The Moment","action":"Open the two suggestions together and make your case for the better choice.","filming":"Capture the conflicting advice and each partner choosing a side.","caption":"The Moment"},{"label":"Payoff","action":"Choose an option together, then give the coaching a very serious rating.","filming":"Record your decision and genuine reaction—even if both suggestions lose.","caption":"Payoff"}],"materials":["Two messages from willing friends","Paper or a phone"],"completionQuestions":["Did the agreed coaching or pit-crew reveal happen, even if the reaction was quiet?","Did everyone shown agree to being recorded, or did you use your own props and an honest private recap?","Did you make the agreed attempt without pressuring anyone to continue?"],"fallback":"Make one elaborate stop at home. Friends can send coaching messages in advance; a homemade welcome, water, and an existing snack are enough.","requirements":["Both partners agree to a playful outing. This is not an unsuspecting first date.","Staff join only by prior agreement. Keep paths clear and reveals brief."],"award":{"xp":100,"points":10},"cooldownDays":30}'::jsonb, true),
