('date_menu_draft_chill_v1', 'date_menu_draft', 1, 'date_night', 'chill', 'The Menu Is Out of Your Hands', '{"id":"date_menu_draft_chill_v1","familyId":"date_menu_draft","version":1,"category":"date_night","intensity":"chill","title":"The Menu Is Out of Your Hands","hook":"Draft the snacks you already have like the championship depends on it.","durationMinutes":30,"minParticipants":2,"maxParticipants":6,"cost":{"minMinor":0,"maxMinor":0,"currency":"USD","scope":"total","venueCostUnknown":true,"note":"Use supplies you already own. Purchases are optional. At a venue, confirm the complete group charge; your travel estimate is added separately."},"settings":["home","venue"],"interests":["mystery_date","competitive","absurd","cooking"],"roles":["main_character","rotate"],"preparation":"start_now","conflicts":[],"venuePermissionRequired":true,"arrangementRequired":false,"adultOnly":false,"supportsAdultContext":false,"requiresVolunteer":false,"beats":[{"label":"Setup","action":"Lay out available snacks, agree on vetoes, and choose the draft order.","filming":"Give the snack candidates a dramatic close-up.","caption":"Setup"},{"label":"The Moment","action":"Each person announces a pick with a ten-second explanation of its supposed greatness.","filming":"Record the most committed selection speech.","caption":"The Moment"},{"label":"Payoff","action":"Try your own approved selection and rate the draft strategy.","filming":"Capture a first-bite verdict or an honest recap if someone prefers not to eat on camera.","caption":"Payoff"}],"materials":["At least two snacks already available","Paper for the draft order"],"completionQuestions":["Did everyone make an agreed draft pick and give an honest verdict?","Did everyone shown agree to being recorded, or did you use your own props and an honest private recap?","Did you make the agreed attempt without pressuring anyone to continue?"],"fallback":"Draft snacks or ingredients already at home. Three existing course choices and a homemad