('day_pitch_swap_bold_v1', 'day_pitch_swap', 1, 'daytime', 'bold', 'The Two-Person Pitch Swap', '{"id":"day_pitch_swap_bold_v1","familyId":"day_pitch_swap","version":1,"category":"daytime","intensity":"bold","title":"The Two-Person Pitch Swap","hook":"You have ten minutes to turn an ordinary object into a ridiculous invention. Then your partner changes the brief.","durationMinutes":45,"minParticipants":2,"maxParticipants":2,"cost":{"minMinor":0,"maxMinor":0,"currency":"USD","scope":"total","venueCostUnknown":true,"note":"Free with two ordinary objects and paper you already own. The 45 minutes includes choosing props, preparing, two pitches, and the verdict. Optional travel is added separately."},"settings":["home","outside"],"interests":["comedy","making","absurd","competitive"],"roles":["main_character","camera_person","rotate"],"preparation":"a_few_things","conflicts":[],"venuePermissionRequired":true,"arrangementRequired":false,"adultOnly":false,"supportsAdultContext":false,"requiresVolunteer":false,"beats":[{"label":"Setup","action":"Spend ten minutes inventing a harmless new use for your object. Agree two playful prompt cards, such as ‘now pitch it to a penguin’ or ‘explain it as a weather forecast’. Each person may veto a prompt before filming.","filming":"Film the ordinary props, preparation, and each person''s confident prediction.","caption":"Setup"},{"label":"The Moment","action":"Take turns delivering a one-minute pitch while the other films or listens. Halfway through, the listener reveals one approved prompt. Keep going in the new style for twenty seconds, then swap roles.","filming":"Record the prompt reveal and the performer''s genuine attempt to adapt, with their permission.","caption":"The Moment"},{"label":"Payoff","action":"Reveal the original objects and give each invention one sincere compliment and one obviously silly award. Failed improvisation is a valid ending; nobody has to repeat a take.","filming":"Capture the two objects, your invented awards, and the pair''s real verdict.","caption":"Payoff"}],"materials":["Two safe ordinary objects already owned","Paper or phone notes","Two willing pitch partners"],"completionQuestions":["Did both people deliver a one-minute pitch and respond to the agreed surprise prompt? A pitch falling apart counts.","Did everyone shown agree to being recorded, or did you use your own props and an honest private recap?","Did you make the agreed attempt without pressuring anyone to continue?"],"fallback":"Stay at home and use a mug or folded paper. If performing on camera is uncomfortable, record the objects and give an honest recap after the live attempt.","requirements":["Two willing people use a space they are allowed to use. No audience, outside cast, purchase, or advance booking is required.","Pitch invented uses for ordinary objects; no real product claims, private disclosures, risky demonstrations, or filming of bystanders."],"award":{"xp":250,"points":25},"cooldownDays":30}'::jsonb, true),
('day_tiny_discovery_chill_v1', 'day_tiny_discovery', 1, 'daytime', 'chill', 'Three Things You Never Noticed', '{"id":"day_tiny_discovery_chill_v1","familyId":"day_tiny_discovery","version":1,"category":"daytime","intensity":"chill","title":"Three Things You Never Noticed","hook":"A tiny expedition through a familiar place, with three details you usually walk past.","durationMinutes":30,"minParticipants":1,"maxParticipants":2,"cost":{"minMinor":0,"maxMinor":0,"currency":"USD","scope":"total","venueCostUnknown":true,"note":"No purchase needed. The 30 minutes includes choosing a small accessible area, looking for details, and filming a short personal verdict. Optional travel is additional."},"settings":["home","outside"],"interests":["local_knowledge","making","spontaneous"],"roles":["mastermind","camera_person","rotate"],"preparation":"start_now","conflicts":[],"venuePermissionRequired":true,"arrangementRequired":false,"adultOnly":false,"supportsAdultContext":false,"requiresVolunteer":false,"beats":[{"label":"Setup","action":"Choose one room or a small familiar outdoor area. Set a fifteen-minute observation window and name three things to look for: an interesting texture, a sign of change, and an overlooked object.","filming":"Film yourself naming the three clues, or show a handwritten clue list.","caption":"Setup"},{"label":"The Moment","action":"Find one real detail for each clue. Stay within your chosen area and film only things you are allowed to show. If with a partner, each contributes at least one discovery.","filming":"Capture a close-up of the discovery you almost missed and explain why it caught your attention.","caption":"The Moment"},{"label":"Payoff","action":"Choose the most surprising discovery and explain how you had overlooked it. An ordinary detail with an honest explanation is enough.","filming":"Record your final discovery and a short genuine verdict on your tiny expedition.","caption":"Payoff"}],"materials":["Your phone","A familiar room or small